import React, { useMemo, useState, useRef } from 'react';
import './App.css';

type CommentNode = {
  id: string;
  text: string;
  children: CommentNode[];
};

export default function App() {
  const [comments, setComments] = useState<CommentNode[]>([]);
  const [topDraft, setTopDraft] = useState('');

  const [activeReplyId, setActiveReplyId] = useState<string | null>(null);
  const [replyDraft, setReplyDraft] = useState('');

  const nextIdRef = useRef(1);
  const makeId = () => String(nextIdRef.current++);

  const addTop = () => {
    const text = topDraft.trim();
    if (!text) return;

    setComments((prev) => [{ id: makeId(), text, children: [] }, ...prev]);
    setTopDraft('');
  };

  const openReply = (id: string) => {
    setActiveReplyId(id);
    setReplyDraft('');
  };

  const cancelReply = () => {
    setActiveReplyId(null);
    setReplyDraft('');
  };

  const findById = (nodes: CommentNode[], id: string): CommentNode | null => {
    for (const n of nodes) {
      if (n.id === id) return n;
      const found = findById(n.children, id);
      if (found) return found;
    }
    return null;
  };

  const submitReply = (parentId: string) => {
    const text = replyDraft.trim();
    if (!text) return;

    setComments((prev) => {
      // Shallow clone root, then mutate the found node's children.
      // OK for this exercise (keeps code small).
      const cloned = structuredClone(prev) as CommentNode[];
      const parent = findById(cloned, parentId);
      if (!parent) return prev;

      parent.children.push({ id: makeId(), text, children: [] });
      return cloned;
    });

    cancelReply();
  };

  const Tree = useMemo(() => {
    const Render = ({ nodes, depth }: { nodes: CommentNode[]; depth: number }) => {
      return (
        <>
          {nodes.map((c) => (
            <div key={c.id} className="node" style={{ marginLeft: depth * 16 }}>
              <div className="bubble">
                <div className="text">{c.text}</div>
                <div className="meta">
                  <button className="ghost" onClick={() => openReply(c.id)}>Reply</button>
                </div>

                {activeReplyId === c.id && (
                  <div className="reply">
                    <input
                      value={replyDraft}
                      onChange={(e) => setReplyDraft(e.target.value)}
                      placeholder="Write a reply..."
                    />
                    <div className="replyActions">
                      <button onClick={() => submitReply(c.id)}>Post</button>
                      <button className="ghost" onClick={cancelReply}>Cancel</button>
                    </div>
                  </div>
                )}
              </div>

              {c.children.length > 0 && <Render nodes={c.children} depth={depth + 1} />}
            </div>
          ))}
        </>
      );
    };
    return Render;
  }, [activeReplyId, replyDraft]);

  return (
    <main className="page">
      <section className="card">
        <h1 className="title">Nested Comments (Solution)</h1>
        <p className="subtitle">Infinite replies, single active reply input, recursive rendering.</p>

        <div className="composer">
          <textarea
            rows={3}
            value={topDraft}
            onChange={(e) => setTopDraft(e.target.value)}
            placeholder="Write a comment..."
          />
          <button onClick={addTop}>Add Comment</button>
        </div>

        <div className="list">
          <Tree nodes={comments} depth={0} />
        </div>

        <div className="hint">Click Reply on different comments: the input should move, not duplicate.</div>
      </section>
    </main>
  );
}

